const cp = require('node:child_process'), os = require('node:os'); //  缺陷名（C-102）**这一栏逐字只写『做完什么』而不写『做完收什么』** ——
//    => 而而它治**的**是「那**落点**逐字**收不收**」。
//    => 而那**成因**：=> 而那 npm **跑一趟**逐字**在**那 HOME **底下**建**那 .npm **那一族**
//       （=> 而那**它**逐字**是**那 _logs **那些**日志**、=> 而而那**它们**逐字**每跑一趟**就**多留**几件**）、
//       => 而而那一栏逐字**没有**那收尾**、=> 而而那**它**们逐字**不**是**那废弃**的**那一种**。
//    => 而那**处置**：=> 而那**它**们逐字**是**那**两**件**事**（=> 而那**判据本体**补**那**一格**、=> 而那**实施**归 05）、
//       => 而而那**处置**逐字**不合并**。
//    => 而按 C-104：=> 而那**收尾**那一族逐字**只有**一条路（=> 而这一支**就是**它**）。
const fs = require('node:fs'); const path = require('node:path');
const npmHome = path.join(process.env.HOME || os.homedir(), '.npm');
try {
const r = cp.spawnSync('npm', ['--version'], { encoding: 'utf8', timeout: 90000 }); if (r.error) { console.error('npm 起不来: ' + r.error.message); process.exit(1); } const v = String(r.stdout || '').trim(); if (r.status !== 0 || v.split('.').length < 3) { console.error('npm 不可用: rc=' + r.status + ' out=' + v.slice(0, 60) + ' err=' + String(r.stderr || '').slice(0, 80)); process.exit(1); } const p = cp.spawnSync('npm', ['config', 'get', 'prefix'], { encoding: 'utf8', timeout: 90000 }); const prefix = String(p.stdout || '').trim(); const home = process.env.HOME || os.homedir(); if (p.status !== 0 || !prefix || prefix.indexOf(home) !== 0) { console.error('npm 的全局前缀不在可写 HOME 下: rc=' + p.status + ' prefix=' + prefix.slice(0, 120) + ' home=' + home + ' err=' + String(p.stderr || '').slice(0, 80)); process.exit(1); } const x = cp.spawnSync('npx', ['--version'], { encoding: 'utf8', timeout: 90000 }); if (x.error) { console.error('npx 起不来（这颗件只兑现了 npm 一颗真名）: ' + x.error.message); process.exit(1); } const xv = String(x.stdout || '').trim(); if (x.status !== 0 || xv.split('.').length < 3) { console.error('npx 不可用: rc=' + x.status + ' out=' + xv.slice(0, 60) + ' err=' + String(x.stderr || '').slice(0, 80)); process.exit(1); } const h = cp.spawnSync('npx', ['--help'], { encoding: 'utf8', timeout: 90000 }); const hs = String(h.stdout || ''); if (h.status !== 0 || hs.indexOf('Run a command from a local or remote npm package') < 0) { console.error('npx 调到了但不是 npx 的真身（--help 打头的不是 exec 语义）: rc=' + h.status + ' out=' + hs.slice(0, 80)); process.exit(1); } process.stdout.write('LOBOS_PROBE_PASS npm=' + v + ' prefix=' + prefix + ' npx=' + xv);} finally {
  try { fs.rmSync(npmHome, { recursive: true, force: true }); } catch (e) {}
}

