const cp = require("node:child_process"), fs = require("node:fs"), os = require("node:os"), path = require("node:path");
const r = cp.spawnSync("make", ["--version"], { encoding: "utf8", timeout: 30000 });
if (r.status !== 0) throw new Error("make 起不来: status=" + r.status + " stderr=" + (r.stderr||"").slice(0,200));

// 编译器：环境里有就用（真编译 C），没有就退回 make 内建的 echo 规则。
// 后者仍能验「makefile 机制通不通」，只是不验 C 编译。
const CC = process.env.CC || null;
const D = fs.mkdtempSync(path.join(os.tmpdir(), "lobos-make-"));
try {
  fs.writeFileSync(path.join(D, "a.c"), "int main(void){return 0;}\n");
  // makefile 用数组逐行写 —— 变量前加 D（"$"）以避开 JS 字符串插值
  const mf = [
    "NAME = demo",
    "all: " + D + "(BINDIR)/" + D + "(NAME)",
    "",
    D + "(BINDIR)/" + D + "(NAME): " + D + "(NAME).o",
    "\t@mkdir -p " + D + "(BINDIR)",
    "\t" + (CC ? D + "(CC) -o " + D + "@ " + D + "<" : "echo built > " + D + "@"),
    "",
    "%.o: %.c",
    "\t" + (CC ? D + "(CC) -c -o " + D + "@ " + D + "<" : "echo obj > " + D + "@"),
    "",
    "clean:",
    "\trm -rf " + D + "(BINDIR) *.o",
    "",
  ].join("\n");
  fs.writeFileSync(path.join(D, "Makefile"), mf);
  const mk = (t) => cp.spawnSync("make", t, { cwd: D, encoding: "utf8", timeout: 120000,
    env: Object.assign({}, process.env, { BINDIR: "out" }, CC ? { CC } : {}) });

  const b1 = mk([]);
  if (b1.status !== 0) throw new Error("make 跑第一条就失败: " + ((b1.stderr || b1.stdout) || "").slice(0, 400));
  const exe = path.join(D, "out", "demo");
  if (!fs.existsSync(exe)) throw new Error("make 报成功但没产出 out/demo —— 它没真建东西（起得来 ≠ 能用）");

  const b2 = mk(["clean"]);
  if (b2.status !== 0) throw new Error("make clean 失败: " + (b2.stderr || "").slice(0, 200));
  if (fs.existsSync(exe)) throw new Error("make clean 跑完但产物还在 —— clean 目标没生效");

  console.log("make ok: " + (CC ? "真编译" : "用内建规则") + "跑通了一条 makefile（含隐式规则），并 clean 干净");
} finally {
  fs.rmSync(D, { recursive: true, force: true });
}

