const cp = require("node:child_process"), fs = require("node:fs"), os = require("node:os"), path = require("node:path");
const r = cp.spawnSync("python3", ["--version"], { encoding: "utf8", timeout: 30000 });
if (r.status !== 0) throw new Error("python3 起不来: status=" + r.status + " stderr=" + (r.stderr||"").slice(0,200));

const D = fs.mkdtempSync(path.join(os.tmpdir(), "lobos-py-"));
try {
  const PY = "import json, collections, os, re, sys

# 算术与内建
assert 2 ** 10 == 1024
assert sum([1, 2, 3]) == 6
assert isinstance(sys.version_info, tuple)

# 标准库：import 成功 ≠ 能用，各调用一次
assert json.loads('{"k": [1, 2]}')["k"] == [1, 2]
assert list(collections.OrderedDict([("a", 1)]).keys()) == ["a"]
assert re.match(r"^a+$", "aaa") is not None
assert os.path.isdir(os.path.dirname(os.path.abspath(__file__))) or True

# 文件读写
p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "t.txt")
with open(p, "w") as f: f.write("hi " + sys.version.split()[0])
with open(p) as f: assert f.read().startswith("hi ")
os.unlink(p)

# 格式化（f-string 要求 3.6+）
n = 42
assert f"{n:03d}" == "042"

print("py-ok", sys.version.split()[0])";
  fs.writeFileSync(path.join(D, "probe.py"), PY);
  const p = cp.spawnSync("python3", ["probe.py"], { cwd: D, encoding: "utf8", timeout: 60000 });
  if (p.status !== 0) {
    throw new Error("跑脚本失败（最可能是标准库没随件走 —— 那时 import 就死，现象是「起得来但一用就崩」）: "
      + ((p.stderr || p.stdout || "").slice(0, 400)));
  }
  const out = (p.stdout || "").trim();
  if (out.indexOf("py-ok") !== 0) throw new Error("没看到 py-ok 输出，实得: " + JSON.stringify(out));
  console.log(out);
} finally {
  fs.rmSync(D, { recursive: true, force: true });
}

